package com.bananalab.lite;
import java.io.*;import java.util.*;import org.json.*;
public class Stage35Check{
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 public static void main(String[] args)throws Exception{String root=args[0];Semilla m=SemillaCheck.load(root+"/assets/language");CreatorSession c=new CreatorSession();SceneDraft start=c.apply(m,"crea a Tony una banana detective con sobretodo",null).commit;String id=start.cast.get(0).designId;
  String[] variants={"Tony habla con el pepino mientras entra el tomate y despues el pepino entrega una caja a Tony y los tres reaccionan","Tony conversa con el pepino mientras el tomate llega por la derecha y luego el pepino pasa una caja a Tony y todos se sorprenden","Tony charla con el pepino mientras aparece el tomate y despues el pepino regala una caja a Tony y los tres se sorprenden"};SceneDraft d=null;for(String q:variants){CreatorSession.Result r=c.apply(m,q,start);check(r.commit!=null,"heldout plan "+r.text);d=r.commit;check(d.cast.size()==3&&d.actions.size()==9,"complete 3-actor plan "+d.actions);check(d.get("tomate")!=null&&PixelGenerator.type("tomate")==9,"new tomato");check(d.get("banana").designId.equals(id)&&d.get("banana").look.equals(start.get("banana").look),"design anchors");check(d.actions.get(0).equals("habla")&&d.slot(0)==d.slot(1)&&d.slot(1)==d.slot(2),"talk while entry");check(ObjectTransfer.at(d,"caja",1,4).owner().equals("banana"),"box destination");System.out.println("PASS heldout "+q);}
  check(c.apply(m,"el que entro saluda",d).commit!=null,"single grounded action");check(c.apply(m,variants[0]+" en la playa",start).commit.setting.equals("playa"),"requested backdrop carried");check(ScenePlanner.resolve(d,"el que entro",false)==d.get("tomate"),"recent arrival reference");check(ScenePlanner.resolve(d,"el que tiene la caja",false)==d.get("banana"),"grounded holder reference");check(ScenePlanner.resolve(d,"el otro",false)==null,"three-way ambiguity");
  SceneDraft light=c.apply(m,"pone el fondo de dia",d).commit;check(light!=null&&light.lighting.equals("day")&&light.get("banana").designId.equals(id)&&light.actions.equals(d.actions),"independent light");SceneDraft fog=c.apply(m,"mucha niebla",light).commit;check(fog.fog==.4f&&fog.cast.size()==3,"independent fog");check(c.apply(m,"agrega un arbol al fondo",fog).commit.sceneryTree,"independent tree");
  SceneDraft damaged=d.copy();damaged.actions.remove(2);damaged.actors.remove(2);damaged.slots.remove(2);damaged.targets.remove(2);damaged.recipients.remove(2);boolean rejected=false;try{PlanAudit.verify(variants[0],start,damaged);}catch(Exception e){rejected=true;}check(rejected,"missing requested action rejected");
  SceneDraft changed=d.copy();changed.get("banana").look="rojo";rejected=false;try{PlanAudit.verify(variants[0],start,changed);}catch(Exception e){rejected=true;}check(rejected,"unrequested appearance mutation rejected");
  Scene scene=new Scene(d);for(float t:new float[]{.51f,.625f,.74f,.7499f,.7501f,1}){float[] point=scene.objectPoint("caja",t);check(!Float.isNaN(point[0])&&!Float.isNaN(point[1]),"finite grip path");}check(Math.abs(scene.handX("banana",.7499f)-scene.handX("banana",.7501f))<.01,"grip stays consistent through turn");float[] joint=JointMath.solve(0,0,10,15,13,14,1);check(Math.abs(joint[2]-10)<.001&&Math.abs(joint[3]-15)<.001,"analytic arm reaches hand");
  Set<String> words=new HashSet<>(Arrays.asList("hola","que","queres","crear","hoy"));check(TextQuality.acceptable("hola que queres crear hoy",words),"normal output");check(!TextQuality.acceptable("pognifi anquis espedado gnio",words),"garbled output blocked");check(!TextQuality.acceptable("hola hola hola hola",words),"repetition blocked");
  System.out.println("PASS ten types, request audit, design identity, context references, environment, hand path and output guard");
 }
}
